/// <summary>
/// Constructs a new METPicklistExtractionBusinessEvent business event.
/// </summary>
/// <param name = "_wmsPickingRoute">The <c>WMSPickingRoute</c> record.</param>
/// <returns>A new <c>METPicklistExtractionBusinessEvent</c> business event.</returns>
public static METPicklistExtractionBusinessEvent newFromWMSPickingRoute(WMSPickingRoute _wmsPickingRoute)
{
    METPicklistExtractionBusinessEvent event = new METPicklistExtractionBusinessEvent();
    event.parmWMSPickingRoute(_wmsPickingRoute);

    return event;
}

/// <summary>
/// Gets and sets <c>WMSPickingRoute</c>.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c>.
/// </param>
/// <returns>
/// <c>WMSPickingRoute</c>.
/// </returns>
private WMSPickingRoute parmWMSPickingRoute(WMSPickingRoute _wmsPickingRoute = wmsPickingRoute)
{
    wmsPickingRoute = _wmsPickingRoute;
    return wmsPickingRoute;
}

/// <summary>
/// Constructs a new METPicklistExtractionBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METPicklistExtractionBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    METPicklistExtractionBusinessEventContract contract = METPicklistExtractionBusinessEventContract::newFromWMSPickingRoute(wmsPickingRoute);
    contract.parmExtractionId(extractionId);
    contract.parmLineCount(lineCount);

    return contract;
}

public static METPicklistExtractionBusinessEvent newFromExtractionContext(METSalesOrderExtractionId _extractionId, int _lineCount)
{
    METPicklistExtractionBusinessEvent event = new METPicklistExtractionBusinessEvent();
    WMSPickingRoute emptyRoute;

    event.parmWMSPickingRoute(emptyRoute);
    event.parmExtractionId(_extractionId);
    event.parmLineCount(_lineCount);

    return event;
}

private METSalesOrderExtractionId parmExtractionId(METSalesOrderExtractionId _extractionId = extractionId)
{
    extractionId = _extractionId;
    return extractionId;
}

private int parmLineCount(int _lineCount = lineCount)
{
    lineCount = _lineCount;
    return lineCount;
}
